-- Recenso F4: dos transacciones de SOLO LECTURA, ejecutadas el 07/09/2026.
-- No aplicar como migracion ni registrar en schema_migrations.
begin read only; set local statement_timeout = '10s'; select jsonb_build_object('observado_en', now(), 'banderas', (select jsonb_object_agg(nombre,activo) from crm.multiempresa_flags), 'inversiones', (select jsonb_build_object('total',count(*),'avance',count(*) filter(where contrato_id is not null),'externas',count(*) filter(where cierre_externo_id is not null)) from crm.inversiones), 'cierres_f2', (select jsonb_build_object('clasificados_B', count(*), 'sin_inversion_enlazada', count(*) filter(where not exists(select 1 from crm.inversiones i where i.cierre_externo_id=m.fila_id and i.inversionista_id=m.inversionista_id)), 'sin_titular_coherente', count(*) filter(where not exists(select 1 from crm.inversiones i join crm.inversion_titulares t on t.inversion_id=i.id and t.rol='principal' and t.inversionista_id=m.inversionista_id where i.cierre_externo_id=m.fila_id and i.inversionista_id=m.inversionista_id))) from crm.backfill_multiempresa_mapa m where fuente='cierre' and clase='B'), 'cierres_no_anulados_sin_inversion', (select count(*) from crm.cierres_externos c where c.anulado_en is null and not exists(select 1 from crm.inversiones i where i.cierre_externo_id=c.id)), 'unicos_cierres', (select jsonb_agg(jsonb_build_object('nombre',conname,'definicion',pg_get_constraintdef(oid))) from pg_constraint where conrelid='crm.cierres_externos'::regclass and contype='u'), 'conversion', (select jsonb_build_object('firma',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),'regla_cartera',substring(p.prosrc from greatest(strpos(p.prosrc,'-- La primera operación ELEGIBLE'),1) for 2000)) from pg_proc p where p.oid='private.conversion_episodios(timestamptz,timestamptz,date,boolean,uuid[],numeric)'::regprocedure), 'funciones_con_inversiones', (select jsonb_agg(jsonb_build_object('firma',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('crm','private','public') and p.prokind='f' and p.prosrc ilike '%insert into crm.inversiones%')) as recenso_f4; rollback;

begin read only; set local statement_timeout = '10s'; select jsonb_build_object('observado_en',now(),'faltante', (select jsonb_agg(jsonb_build_object('registrado_en',c.creado_en,'empresa',c.cooperativa,'tiene_identidad',c.inversionista_id is not null,'clase_f2',m.clase,'regla_f2',m.regla,'documento_valido',coalesce(case c.documento_tipo when 'DNI' then upper(regexp_replace(c.documento,'[^A-Za-z0-9]','','g')) ~ '^[0-9]{8}$' when 'CE' then upper(regexp_replace(c.documento,'[^A-Za-z0-9]','','g')) ~ '^[0-9]{9,12}$' when 'PASAPORTE' then upper(regexp_replace(c.documento,'[^A-Za-z0-9]','','g')) ~ '^[A-Z0-9]{6,12}$' else false end,false))) from crm.cierres_externos c left join crm.backfill_multiempresa_mapa m on m.fuente='cierre' and m.fila_id=c.id where c.anulado_en is null and not exists(select 1 from crm.inversiones i where i.cierre_externo_id=c.id)), 'alta_contrato', (select jsonb_agg(jsonb_build_object('firma',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),'regla_upgrade',substring(p.prosrc from greatest(strpos(p.prosrc, 'if v_categoria = ''upgrade'' then'),1) for 950))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='crear_contrato'), 'capital_md5', (select md5(pg_get_functiondef(p.oid)) from pg_proc p where p.oid='private.capital_episodios(timestamptz,timestamptz,boolean,uuid[])'::regprocedure)) as detalle_f4; rollback;
